Here is the code for a basic Discord bot that implements a ban command using Discord.js v14:
```javascript
const { Client, Intents } = require('discord.js');
const { token } = require('./config.json');

// Create a new client instance
const client = new Client({ intents: [Intents.FLAGS.GUILDS] });

// Login to the bot
client.login(token);

// Register an event listener for when the bot is ready
client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
});

// Create a ban command
client.commands = new Map();
client.commands.set('ban', {
  name: 'ban',
  description: 'Ban a user from the server.',
  execute: async (message, args) => {
    // Check if the user has permission to use this command
    if (!message.member.permissions.has('BAN_MEMBERS')) {
      return message.channel.send('You do not have permission to use this command.');
    }

    // Get the user to ban
    const member = message.mentions.members.first();

    // Check if a user was mentioned
    if (!member) {
      return message.channel.send('Please mention a user to ban.');
    }

    // Check if the user can be banned
    if (!member.bannable) {
      return message.channel.send('This user cannot be banned.');
    }

    // Confirm the ban action
    const confirmation = await message.channel.send(`Are you sure you want to ban ${member}?`);
    await confirmation.awaitReactions((reaction, user) => user.id === message.author.id && ['✅', '❌'].includes(reaction.emoji.name), { max: 1 });
    const reaction = confirmation.reactions.cache.get('✅') || confirmation.reactions.cache.get('❌');
    if (!reaction) {
      return;
    }

    // Ban the user
    if (reaction.emoji.name === '✅') {
      await member.ban();
      message.channel.send(`User ${member} has been banned.`);
    } else {
      message.channel.send('Ban cancelled.');
    }
  },
});

// Export the client
module.exports = client;
```
This code creates a simple Discord bot that can be used to ban users from the server. The bot has a single command called "ban", which can only be used by members with the BAN_MEMBERS permission. When invoked, the bot prompts the user to confirm the ban action and then bans

