Design a function to calculate the maximum sum of any contiguous subsequence in a given sequence of numbers. For example, given the sequence [3, 4, 2, -1, 5, 4], the maximum sum would be 9 (from elements 3 and 6).

// Define input sequence
let sequence = [3, 4, 2, -1, 5, 4]

// Define a function to calculate maximum sum of any contiguous subsequence
function maxSubsequenceSum(sequence) {
  let maxSum = sequence[0];

  for (let i = 0; i < sequence.length; i++) {
    let currentSum = 0;
    for (let j = i; j < sequence.length; j++) {
      currentSum += sequence[j];
      maxSum = Math.max(maxSum, currentSum);
    }
  }

  return maxSum;
}

// Test the function
console.log(maxSubsequenceSum(sequence)); // Output: 9userlásil

