#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    string word; // word to search for
    int count = 0; // counter variable

    cout << "Enter the word to search for: ";
    getline(cin, word);

    ifstream infile("filename.txt"); // replace 'filename' with actual file name
    if (infile) {
        string line;
        while (getline(infile, line)) {
            size_t pos = line.find(word);
            while (pos!= string::npos) {
                count++;
                pos = line.find(word, pos + 1);
            }
        }
        cout << "The word appeared " << count << " times." << endl;
    } else {
        cerr << "Error opening file." << endl;
    }
    return 0;
}
``` 
