class Queue:
    def __init__(self):
        self.first_stack = []
        self.second_stack = []

    def enqueue(self, item):
        self.first_stack.append(item)

    def dequeue(self):
        if len(self.second_stack) == 0:
            while len(self.first_stack) > 0:
                self.second_stack.append(self.first_stack.pop())
        return self.second_stack.pop()assistant

